<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#C0CAF5;">    points</span><span style="--shiki-light:#0E1116;--shiki-dark:#A9B1D6;">: </span><span style="--shiki-light:#023B95;--shiki-dark:#0DB9D7;">integer</span></span>
